    inner_width = max(10, width - 4)
    border_top = '╔' + '═' * inner_width + '╗'
    border_mid = '║ '
    border_end = ' ║'
    border_bot = '╚' + '═' * inner_width + '╝'
    print(gradient_text(border_top, c1, c2))
    padded_text = text.center(inner_width)
    print(gradient_text(border_mid, c1, c2) + padded_text + gradient_text(border_end, c1, c2))
    print(gradient_text(border_bot, c1, c2))

